    TextureV6 createTexture8(const char*path,VkFormat fmt,bool clamp=false){auto bytes=assetBytes(path);int w=0,h=0,c=0;stbi_uc*p=stbi_load_from_memory(bytes.data(),static_cast<int>(bytes.size()),&w,&h,&c,STBI_rgb_alpha);if(!p)throw std::runtime_error(std::string("stb decode failed: ")+path);TextureV6 t=createTextureRaw(p,static_cast<size_t>(w)*static_cast<size_t>(h)*4u,w,h,fmt,clamp);stbi_image_free(p);return t;}
    TextureV6 createTextureHdr(const char*path){auto bytes=assetBytes(path);int w=0,h=0,c=0;float*p=stbi_loadf_from_memory(bytes.data(),static_cast<int>(bytes.size()),&w,&h,&c,STBI_rgb_alpha);if(!p)throw std::runtime_error(std::string("HDR decode failed: ")+path);std::vector<uint16_t>half(static_cast<size_t>(w)*static_cast<size_t>(h)*4u);for(size_t i=0;i<half.size();++i)half[i]=f16(std::clamp(p[i],0.0f,65504.0f));stbi_image_free(p);return createTextureRaw(half.data(),half.size()*sizeof(uint16_t),w,h,VK_FORMAT_R16G16B16A16_SFLOAT,true);}

