        VkMemoryRequirements mr{};vkGetImageMemoryRequirements(device_,t.image,&mr);VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};ai.allocationSize=mr.size;ai.memoryTypeIndex=memType(mr.memoryTypeBits,VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);checkVk(vkAllocateMemory(device_,&ai,nullptr,&t.memory),"v6 texture memory");checkVk(vkBindImageMemory(device_,t.image,t.memory,0),"v6 texture bind");
