        VkBufferImageCopy region{};region.imageSubresource.aspectMask=VK_IMAGE_ASPECT_COLOR_BIT;region.imageSubresource.layerCount=1;region.imageExtent={t.width,t.height,1};vkCmdCopyBufferToImage(cmd,staging.buffer,t.image,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,1,&region);
