    void destroyTexture(TextureV6&t){if(!device_)return;if(t.sampler)vkDestroySampler(device_,t.sampler,nullptr);if(t.view)vkDestroyImageView(device_,t.view,nullptr);if(t.image)vkDestroyImage(device_,t.image,nullptr);if(t.memory)vkFreeMemory(device_,t.memory,nullptr);t={};}
    void loadTexturesV6(){floorAlb_=createTexture8("vulkan_v6/slab_tiles_diff_2k.jpg",VK_FORMAT_R8G8B8A8_SRGB);floorNormal_=createTexture8("vulkan_v6/slab_tiles_nor_gl_2k.jpg",VK_FORMAT_R8G8B8A8_UNORM);floorArm_=createTexture8("vulkan_v6/slab_tiles_arm_2k.jpg",VK_FORMAT_R8G8B8A8_UNORM);floorHeight_=createTexture8("vulkan_v6/slab_tiles_disp_2k.png",VK_FORMAT_R8G8B8A8_UNORM);concreteAlb_=createTexture8("vulkan_v6/rough_concrete_diff_2k.jpg",VK_FORMAT_R8G8B8A8_SRGB);concreteNormal_=createTexture8("vulkan_v6/rough_concrete_nor_gl_2k.jpg",VK_FORMAT_R8G8B8A8_UNORM);concreteArm_=createTexture8("vulkan_v6/rough_concrete_arm_2k.jpg",VK_FORMAT_R8G8B8A8_UNORM);concreteHeight_=createTexture8("vulkan_v6/rough_concrete_disp_2k.png",VK_FORMAT_R8G8B8A8_UNORM);environment_=createTextureHdr("vulkan_v6/evening_museum_courtyard_1k.hdr");logV6("PBR assets loaded · slab tile + rough concrete + 1K HDR environment");}

    std::vector<Vec3>roundedCubeTrianglesV6(){std::vector<Vec3>v;v.reserve(kV6HeroVerts);auto facePoint=[](int face,float u,float vv){Vec3 unit;float a=u*2-1,b=vv*2-1;if(face==0)unit={a,b,1};else if(face==1)unit={-a,b,-1};else if(face==2)unit={1,b,-a};else if(face==3)unit={-1,b,a};else if(face==4)unit={a,1,-b};else unit={a,-1,b};Vec3 he{1.18f,1.02f,1.18f},in{1.075f,.915f,1.075f};Vec3 raw{unit.x*he.x,unit.y*he.y,unit.z*he.z};Vec3 c{std::clamp(raw.x,-in.x,in.x),std::clamp(raw.y,-in.y,in.y),std::clamp(raw.z,-in.z,in.z)};Vec3 d=raw-c;return c+norm(d)*.105f;};for(int f=0;f<6;++f)for(uint32_t y=0;y<kV6HeroGrid;++y)for(uint32_t x=0;x<kV6HeroGrid;++x){float u0=float(x)/kV6HeroGrid,u1=float(x+1)/kV6HeroGrid,v0=float(y)/kV6HeroGrid,v1=float(y+1)/kV6HeroGrid;Vec3 a=facePoint(f,u0,v0),b=facePoint(f,u1,v0),c=facePoint(f,u1,v1),d=facePoint(f,u0,v1);v.insert(v.end(),{a,b,c,a,c,d});}return v;}

    int activeBodiesV6()const{if(!stress_.load())return static_cast<int>(kV6QualityBodies);int extras=std::clamp(10+(quality_.load()*30)/100,10,40);return static_cast<int>(kV6QualityBodies)+extras;}
    void configureBodiesV6(){std::lock_guard<std::mutex>lock(bodyMutex_);configureBodiesLockedV6();}
    void configureBodiesLockedV6(){if(bodies_.size()<kV6QualityBodies)return;auto setup=[&](int i,Vec3 p,float r,int mat,float rest,float fric,float density,bool gummy=false){Body&b=bodies_[i];b.p=p;b.v={};b.r=r;b.material=mat;b.restitution=rest;b.friction=fric;b.gummy=gummy;b.deform=b.deformV=0;b.mass=std::max(.18f,4.18879f*r*r*r*density);};setup(0,{-2.15f,kFloorY+.70f,-.25f},.70f,2,.26f,.30f,6.8f);setup(1,{.60f,kFloorY+.72f,.35f},.72f,3,.62f,.25f,1.10f,true);setup(2,{-.45f,2.45f,-2.05f},.34f,4,.28f,.33f,1.0f);setup(3,{2.28f,kFloorY+.66f,-.18f},.66f,7,.32f,.34f,1.55f);setup(4,{-.55f,kFloorY+.62f,1.85f},.62f,9,.38f,.30f,1.30f);for(int i=5;i<kBodyCount;++i){int n=i-5,gx=n%8,gz=n/8;float r=.25f+.025f*float((n*7)%4);int mat=(n%7==0)?8:((n%4==0)?6:((n%3==0)?7:2));float density=mat==8?5.1f:(mat==2?5.8f:1.7f);setup(i,{(float(gx)-3.5f)*1.10f,kFloorY+r+.10f*float(n%3),(float(gz)-2.2f)*1.08f},r,mat,.28f+.04f*float(n%3),.38f,density);}omega_.fill({});spin_.fill(0);}
    Vec3 clampInsideV6(Vec3 p,float r)const{p.x=std::clamp(p.x,-kV6RoomHalf+r,kV6RoomHalf-r);p.z=std::clamp(p.z,-kV6RoomHalf+r,kV6RoomHalf-r);p.y=std::clamp(p.y,kFloorY+r,kV6Ceiling-r);return p;}

